w=Path('work').resolve();p=w/'hekate-nova-pro-v34-alpha7';o=w.parent/'outputs';sha=lambda b:hashlib.sha256(b).hexdigest()
for n in ('nova34a7-tv-driver-check.json','nova34a7-tv-integration.json','nova34a7-header-check.json','nova34a7-copy-check.json','nova34a7-partition-check.json','nova34a7-fatfs-check.json'):assert json.loads((w/n).read_text())['passed']
assert 'PASS' in json.loads((w/'nova34a7-tv-lifecycle-check.json').read_text())['result']
note="Hekate Nova Pro v34 alpha 7 — maintien d'une image réellement reçue\n\nRetours alpha6 run-025 à run-029 : l'image apparaît puis disparaît, activation régulière. HBR2 perd l'égalisation. En HBR/RBR, les voies sont alignées, les compteurs d'erreurs valides sont à zéro et le récepteur compte des captures CRC en RBR, mais SINK_STATUS reste nul. L'alpha6 coupait alors la sortie : son contrôle de synchronisation était trop strict pour ce dock.\n\n- Validation alternative par des captures CRC fraîches du récepteur si SINK_STATUS reste nul. Exiger l'avancement du compteur après activation de la capture, toutes les lectures/écritures AUX réussies, une source active, des compteurs d'erreurs valides à zéro et cinq lectures consécutives de voies alignées (80 ms). Une ancienne valeur CRC non nulle ne suffit pas.\n- Le début du compteur est lu après activation, pour éviter de prendre sa remise à zéro pour des images reçues. La capture est arrêtée après le contrôle et un échec de cet arrêt invalide la preuve.\n- La présence d'une TV seule (SIGNAL_ON, cas 4182 des run-026/028) ne déclenche plus Exit DP lorsque DP_EN est déjà nul. Cela évite la commande refusée par le contrôleur pour un mode déjà arrêté.\n- Conservation du débit initial puis des replis HBR/RBR, du nettoyage d'un vrai mode DP actif et des arrêts au retrait/commande manuelle. Service TV pendant les opérations longues et journaux différés conservés.\n\nCompilation ARM, en-têtes, 54 scénarios du service, 957 assertions du pilote et intégration aux boucles longues vérifiés sur PC. Les contrôles de copie/partitionnement/FatFs de l'alpha6 restent applicables aux sources identiques, vérifiées par empreintes. Aucun essai HDMI ni écriture sur une SD physique ici. Le retour d'image alpha6 est celui rapporté par l'utilisateur ; la stabilité alpha7 reste à confirmer.\n\nInstaller le pack complet et employer son payload alpha7. Garder les réglages existants et Standard pour une console non modifiée en RAM. Tester d'abord la permanence de l'image au démarrage et après retrait/remise sur dock officiel. Les nouveaux journaux doivent indiquer 34-alpha7 ; si la validation alternative est utilisée, ils contiennent 'video stream confirmed by fresh sink CRC frames and stable lanes'. En cas de coupure, transmettre les derniers run-*.txt et last-run.txt de bootloader/tv-test. Valider l'affichage avant de tester les opérations longues. Sauvegarder les données SD avant partitionnement.\n\nLe pack 8GB expérimental reste destiné aux consoles physiquement modifiées. Aucun upload GitHub de cette alpha.\n"
(o/'LIRE-MOI-NOVA34-ALPHA7.txt').write_text(note,encoding='utf-8');(p/'ASSISTANT-V34-ALPHA7.txt').write_text(note,encoding='utf-8')
translations={'fr':'Maintien du service TV pendant les opérations longues, rafraîchissement après chaque image terminée, journaux TV différés pour éviter tout accès SD réentrant. Attentes de boutons coopératives. Réglages et arrêts matériels conservés. Validation matérielle à effectuer.','en':'Keep TV serviced during long operations, present completed frames, defer TV logs to avoid reentrant SD access, and service physical-button waits. Preserve settings and hardware shutdown guards. Physical validation pending.','es':'Servicio TV durante operaciones largas y esperas de botones. Presentación de imágenes completas y registros diferidos sin acceso SD simultáneo. Ajustes y protecciones conservados. Falta validación física.','it':'Servizio TV durante operazioni lunghe e attese dei pulsanti. Immagini complete e registri differiti senza accesso SD rientrante. Impostazioni e protezioni mantenute. Verifica hardware da eseguire.','de':'TV-Dienst während langer Vorgänge und Tastenwartezeiten. Fertige Bilder übertragen, Protokolle ohne rekursiven SD-Zugriff verzögern. Einstellungen und Schutzabschaltungen bleiben erhalten. Hardwareprüfung ausstehend.','pt':'Serviço TV durante operações longas e esperas de botões. Imagens completas e registos adiados sem acesso SD recursivo. Definições e proteções mantidas. Validação física pendente.','ru':'Обслуживание TV во время длительных операций и ожидания кнопок. Передача готовых кадров и отложенная запись журналов без повторного доступа к SD. Настройки и защитные отключения сохранены. Проверка на консоли ожидается.','zh-CN':'长时间操作和等待按键时保持 TV 服务，完成画面后更新输出，延迟保存日志以避免重复访问 SD。保留设置和硬件保护，仍需实机验证。'}
for key,value in {'fr': ' Jusqu’à trois tentatives espacées après échec de connexion ; aucun reset PD forcé et arrêt manuel prioritaire.', 'en': ' Up to three spaced attempts after connection failure; no forced PD reset and manual stop takes priority.', 'es': ' Hasta tres intentos espaciados tras fallo; sin reinicio PD forzado y parada manual prioritaria.', 'it': ' Fino a tre tentativi distanziati dopo un errore; nessun reset PD forzato e arresto manuale prioritario.', 'de': ' Bis zu drei zeitversetzte Versuche nach Verbindungsfehler; kein erzwungener PD-Reset, manueller Stopp hat Vorrang.', 'pt': ' Até três tentativas espaçadas após falha; sem reset PD forçado e paragem manual prioritária.', 'ru': ' До трёх попыток с паузами после ошибки связи; без принудительного сброса PD, ручная остановка имеет приоритет.', 'zh-CN': ' 连接失败后最多间隔重试三次，不强制重置 PD，手动停止优先。'}.items():translations[key]+=value
for key,value in {'fr':' Confirmation fraîche de synchronisation vidéo (attente bornée à 1 s) ; échec explicite sans synchronisation/AUX/HPD. Numéro de journal corrigé.', 'en':' Require fresh video stream sync within 1 s; fail explicitly on missing sync/AUX/HPD. Correct log version.', 'es':' Confirmación nueva de sincronización en 1 s; error explícito sin sincronización/AUX/HPD. Versión del registro corregida.', 'it':' Conferma aggiornata della sincronizzazione entro 1 s; errore esplicito senza sincronizzazione/AUX/HPD. Versione registro corretta.', 'de':' Frische Videosynchronisation innerhalb 1 s erforderlich; Fehler bei fehlendem Sync/AUX/HPD. Protokollversion korrigiert.', 'pt':' Confirmação atual da sincronização em 1 s; erro explícito sem sincronização/AUX/HPD. Versão do registo corrigida.', 'ru':' Требуется свежее подтверждение синхронизации за 1 с; явная ошибка при отсутствии синхронизации/AUX/HPD. Версия журнала исправлена.', 'zh-CN':' 最多等待 1 秒获取最新视频同步确认；同步、AUX 或 HPD 失败时明确报错，修正日志版本。'}.items():translations[key]+=value
for key,value in {'fr':' Alpha6 : sortie contrôlée du mode DP hérité avant identification ; repli du seul lien vidéo vers HBR/RBR après perte de synchronisation, avec contrôle frais de toutes les voies. 429 assertions du pilote et 54 scénarios du service réussis sur PC ; essai console requis.', 'en':' Alpha6: exit inherited DP mode before discovery; retry only the video link at HBR/RBR after stream-sync failure, checking fresh lane status. 429 driver assertions and 54 service scenarios passed on PC; console testing required.', 'es':' Alpha6: salir del modo DP heredado antes de identificar el dock; reintentar el enlace de vídeo a HBR/RBR tras un fallo de sincronización, comprobando las vías. 429 comprobaciones del controlador y 54 escenarios de servicio superados en PC; falta prueba en consola.', 'it':' Alpha6: uscita controllata dalla modalità DP ereditata prima di identificare il dock; ripetizione del collegamento video a HBR/RBR dopo mancata sincronizzazione, verificando le linee. 429 verifiche del driver e 54 scenari superati su PC; prova console necessaria.', 'de':' Alpha6: geerbten DP-Modus vor der Erkennung verlassen; bei fehlender Videosynchronisation nur den Videolink mit HBR/RBR neu starten und aktuelle Lane-Statuswerte prüfen. 429 Treiberprüfungen und 54 Dienstszenarien auf PC bestanden; Konsolentest erforderlich.', 'pt':' Alpha6: saída controlada do modo DP herdado antes de identificar o dock; nova tentativa apenas do enlace de vídeo em HBR/RBR após falha de sincronização, verificando as vias. 429 verificações do controlador e 54 cenários aprovados no PC; falta teste na consola.', 'ru':' Alpha6: управляемый выход из унаследованного режима DP до обнаружения дока; повтор видеолинии на HBR/RBR при потере синхронизации с проверкой текущего состояния каналов. На ПК пройдено 429 проверок драйвера и 54 сценария службы; нужен тест на консоли.', 'zh-CN':' Alpha6：识别底座前受控退出遗留 DP 模式；视频同步失败时仅以 HBR/RBR 重试视频链路，并读取各通道最新状态。PC 已通过 429 项驱动断言和 54 个服务场景，仍需主机实测。'}.items():translations[key]+=value
for key,value in {'fr':' Alpha7 : éviter la coupure d’un flux reçu lorsque SINK_STATUS reste nul. Confirmation alternative par compteur CRC frais, source active, compteurs d’erreurs valides à zéro et cinq lectures de voies alignées. Contrôle des erreurs AUX et du redémarrage du compteur. Ne plus envoyer Exit DP pour SIGNAL_ON seul. Stabilité sur console à confirmer.', 'en':' Alpha7: avoid stopping received video when SINK_STATUS stays clear. Alternative verification requires fresh sink CRC progress, an active source, valid zero symbol errors and five aligned lane reads. Check all AUX failures and capture-counter reset. Do not send Exit DP for SIGNAL_ON alone. Console stability pending.', 'es':' Alpha7: evitar cortar el vídeo recibido cuando SINK_STATUS permanece a cero. Validación alternativa con avance CRC nuevo, fuente activa, errores válidos a cero y cinco lecturas de vías alineadas. Comprobar AUX y reinicio del contador. No enviar Exit DP por SIGNAL_ON solo. Falta validar estabilidad en consola.', 'it':' Alpha7: evitare di interrompere il video ricevuto quando SINK_STATUS resta a zero. Verifica alternativa con nuovi CRC, sorgente attiva, errori validi a zero e cinque letture delle linee allineate. Controlli AUX e reset del contatore. Nessun Exit DP per il solo SIGNAL_ON. Stabilità console da verificare.', 'de':' Alpha7: empfangenes Video bei SINK_STATUS=0 nicht abschalten. Alternative Bestätigung durch frische CRC-Fortschritte, aktive Quelle, gültige Null-Fehlerzähler und fünf ausgerichtete Lane-Lesevorgänge. AUX-Fehler und Zählerrücksetzung prüfen. Kein Exit DP nur wegen SIGNAL_ON. Konsolenstabilität noch zu prüfen.', 'pt':' Alpha7: evitar cortar vídeo recebido quando SINK_STATUS fica a zero. Verificação alternativa com progresso CRC novo, fonte ativa, erros válidos a zero e cinco leituras de vias alinhadas. Verificar AUX e reinício do contador. Não enviar Exit DP apenas por SIGNAL_ON. Estabilidade na consola por confirmar.', 'ru':' Alpha7: не отключать принимаемое видео при нулевом SINK_STATUS. Альтернативная проверка: новые CRC, активный источник, действительные нулевые счётчики ошибок и пять чтений выровненных каналов. Проверка AUX и сброса счётчика. SIGNAL_ON сам по себе не вызывает Exit DP. Стабильность на консоли ещё не подтверждена.', 'zh-CN':' Alpha7：SINK_STATUS 为零时，不再仅因此切断已接收的视频。替代验证要求新的 CRC 计数进展、活动信号源、有效且为零的错误计数，以及连续五次通道对齐读数。检查所有 AUX 错误和计数器重置；仅有 SIGNAL_ON 时不发送 Exit DP。稳定性仍需实机确认。'}.items():translations[key]+=value
reports=['nova34a7-tv-driver-check.json','nova34a7-tv-lifecycle-check.json','nova34a7-tv-integration.json','nova34a7-header-check.json','nova34a7-copy-check.json','nova34a7-partition-check.json','nova34a7-fatfs-check.json']
