for suffix in ('','-8GB'):
 with ZipFile(o/('hekate-nova-pro-v34-alpha4'+suffix+'.zip'))as z:files={n:z.read(n)for n in z.namelist()if not n.endswith('/')and not n.startswith('hekate_nova_pro_')and n not in ('BUILD-INFO.json','BUNDLE-MANIFEST.json')}
 for n in ('nyx.bin','libsys_lp0.bso','libsys_minerva.bso'):files['bootloader/sys/'+n]=(p/'output'/n).read_bytes()
 payload=bytearray((p/'output/hekate.bin').read_bytes());assert not payload[0x122]&1
 if suffix:payload[0x122]|=1
 name='hekate_nova_pro_6.5.5_v34_alpha7'+('_8GB_EXPERIMENTAL'if suffix else'')+'.bin';files[name]=files['bootloader/update.bin']=files['bootloader/payloads/'+name]=bytes(payload)
 files['LIRE-MOI.txt']=note.encode();files['documentation/TV-V34-ALPHA7.txt']=note.encode()
 for code,t in translations.items():files['documentation/changelogs/CHANGELOG-NOVA34-ALPHA7-'+code+'.md']=('# Hekate Nova Pro v34 alpha 7\n\n'+t+'\n').encode()
 for n in reports:files['verification/'+n]=(w/n).read_bytes()
 files['BUILD-INFO.json']=json.dumps({'version':'34-alpha7','variant':'8GB-experimental'if suffix else'standard','compiled':True,'physical_console_test':False,'tv_long_operations':True},indent=2).encode()
 files['BUNDLE-MANIFEST.json']=json.dumps({n:sha(b)for n,b in files.items()},indent=2).encode()
 target=o/('hekate-nova-pro-v34-alpha7'+suffix+'.zip');assert not target.exists()
 with ZipFile(target,'w',ZIP_DEFLATED,compresslevel=6)as z:
  for n,b in sorted(files.items()):z.writestr(n,b)
 with ZipFile(target)as z:assert z.testzip()is None
 summary[target.name]={'bytes':target.stat().st_size,'sha256':sha(target.read_bytes())}
# Complete source and unchanged standalone diagnostic dependencies.
with ZipFile(o/'hekate-nova-pro-v34-alpha4-sources.zip')as z:files={n:z.read(n)for n in z.namelist()if not n.endswith('/')and not n.startswith('hekate-nova-pro-v34-alpha4/')}
for f in p.rglob('*'):
 if f.is_file()and not any(x in ('build','output','.git','__pycache__')for x in f.relative_to(p).parts)and f.name not in ('payload_00.h','payload_01.h'):files['hekate-nova-pro-v34-alpha7/'+f.relative_to(p).as_posix()]=f.read_bytes()
